// {n, t:[ar title, en title], a:[arabic paragraphs], e:[english paragraphs], s:source, v:[[ar,en],...]}
window.ARBAIN = [
{n:1,t:['إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ','Actions are by intentions'],
a:['عَنْ أَمِيرِ الْمُؤْمِنِينَ أَبِي حَفْصٍ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ ﷺ يَقُولُ: «إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللهِ وَرَسُولِهِ فَهِجْرَتُهُ إِلَى اللهِ وَرَسُولِهِ، وَمَنْ كَانَتْ هِجْرَتُهُ لِدُنْيَا يُصِيبُهَا أَوِ امْرَأَةٍ يَنْكِحُهَا فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ».'],
e:['From the Commander of the Believers, Abū Ḥafṣ ʿUmar ibn al-Khaṭṭāb, who said: I heard the Messenger of Allah ﷺ say: “Actions are only by intentions, and every person will have only what he intended. So whoever’s emigration was to Allah and His Messenger, his emigration is to Allah and His Messenger; and whoever’s emigration was for some worldly gain he wanted, or a woman he wished to marry, his emigration is to whatever he emigrated for.”'],
s:'رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ',v:[['الْأَعْمَالُ','actions'],['النِّيَّاتُ','intentions'],['امْرِئٍ','a person'],['نَوَى','he intended'],['هِجْرَةٌ','emigration'],['يُصِيبُهَا','he would obtain it'],['يَنْكِحُهَا','he would marry her']]},

{n:2,t:['الْإِسْلَامُ وَالْإِيمَانُ وَالْإِحْسَانُ','Islam, Īmān and Iḥsān (the ḥadīth of Jibrīl)'],
a:['عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُ أَيْضًا قَالَ: بَيْنَمَا نَحْنُ جُلُوسٌ عِنْدَ رَسُولِ اللهِ ﷺ ذَاتَ يَوْمٍ، إِذْ طَلَعَ عَلَيْنَا رَجُلٌ شَدِيدُ بَيَاضِ الثِّيَابِ، شَدِيدُ سَوَادِ الشَّعَرِ، لَا يُرَى عَلَيْهِ أَثَرُ السَّفَرِ، وَلَا يَعْرِفُهُ مِنَّا أَحَدٌ، حَتَّى جَلَسَ إِلَى النَّبِيِّ ﷺ، فَأَسْنَدَ رُكْبَتَيْهِ إِلَى رُكْبَتَيْهِ، وَوَضَعَ كَفَّيْهِ عَلَى فَخِذَيْهِ، وَقَالَ: يَا مُحَمَّدُ، أَخْبِرْنِي عَنِ الْإِسْلَامِ.',
'فَقَالَ رَسُولُ اللهِ ﷺ: «الْإِسْلَامُ أَنْ تَشْهَدَ أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللهِ، وَتُقِيمَ الصَّلَاةَ، وَتُؤْتِيَ الزَّكَاةَ، وَتَصُومَ رَمَضَانَ، وَتَحُجَّ الْبَيْتَ إِنِ اسْتَطَعْتَ إِلَيْهِ سَبِيلًا». قَالَ: صَدَقْتَ. فَعَجِبْنَا لَهُ يَسْأَلُهُ وَيُصَدِّقُهُ!',
'قَالَ: فَأَخْبِرْنِي عَنِ الْإِيمَانِ. قَالَ: «أَنْ تُؤْمِنَ بِاللهِ، وَمَلَائِكَتِهِ، وَكُتُبِهِ، وَرُسُلِهِ، وَالْيَوْمِ الْآخِرِ، وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ». قَالَ: صَدَقْتَ.',
'قَالَ: فَأَخْبِرْنِي عَنِ الْإِحْسَانِ. قَالَ: «أَنْ تَعْبُدَ اللهَ كَأَنَّكَ تَرَاهُ، فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ».',
'قَالَ: فَأَخْبِرْنِي عَنِ السَّاعَةِ. قَالَ: «مَا الْمَسْئُولُ عَنْهَا بِأَعْلَمَ مِنَ السَّائِلِ». قَالَ: فَأَخْبِرْنِي عَنْ أَمَارَاتِهَا. قَالَ: «أَنْ تَلِدَ الْأَمَةُ رَبَّتَهَا، وَأَنْ تَرَى الْحُفَاةَ الْعُرَاةَ الْعَالَةَ رِعَاءَ الشَّاءِ يَتَطَاوَلُونَ فِي الْبُنْيَانِ».',
'ثُمَّ انْطَلَقَ، فَلَبِثْتُ مَلِيًّا، ثُمَّ قَالَ: «يَا عُمَرُ، أَتَدْرِي مَنِ السَّائِلُ؟» قُلْتُ: اللهُ وَرَسُولُهُ أَعْلَمُ. قَالَ: «فَإِنَّهُ جِبْرِيلُ أَتَاكُمْ يُعَلِّمُكُمْ دِينَكُمْ».'],
e:['Also from ʿUmar, who said: One day while we were sitting with the Messenger of Allah ﷺ, a man appeared before us with very white clothes and very black hair. No sign of travel could be seen on him, and none of us knew him. He sat down by the Prophet ﷺ, rested his knees against his knees, placed his palms on his thighs and said: “O Muḥammad, tell me about Islam.”',
'The Messenger of Allah ﷺ said: “Islam is that you testify that there is no god but Allah and that Muḥammad is the Messenger of Allah, establish the prayer, give the zakāh, fast Ramaḍān, and perform Hajj to the House if you are able to find a way to it.” He said: “You have spoken truly.” We were amazed at him asking and then confirming the answer.',
'He said: “Tell me about īmān.” He said: “That you believe in Allah, His angels, His books, His messengers and the Last Day, and that you believe in the decree, its good and its bad.” He said: “You have spoken truly.”',
'He said: “Tell me about iḥsān.” He said: “That you worship Allah as though you see Him, and if you do not see Him, then indeed He sees you.”',
'He said: “Tell me about the Hour.” He said: “The one asked about it knows no more than the one asking.” He said: “Then tell me about its signs.” He said: “That the slave-woman gives birth to her mistress, and that you see the barefoot, unclothed, destitute shepherds competing in constructing tall buildings.”',
'Then he left, and I stayed a while. Then he said: “O ʿUmar, do you know who the questioner was?” I said: “Allah and His Messenger know best.” He said: “That was Jibrīl, who came to you to teach you your religion.”'],
s:'رَوَاهُ مُسْلِمٌ',v:[['طَلَعَ','appeared'],['أَسْنَدَ','he rested, leaned'],['رُكْبَتَيْهِ','his two knees'],['فَخِذَيْهِ','his two thighs'],['الْقَدَرُ','the divine decree'],['أَمَارَاتٌ','signs'],['الْأَمَةُ','slave-woman'],['الْحُفَاةُ','the barefoot'],['الْعُرَاةُ','the unclothed'],['الْعَالَةُ','the destitute'],['رِعَاءُ الشَّاءِ','shepherds'],['يَتَطَاوَلُونَ','they compete in height'],['مَلِيًّا','a long while']]},

{n:3,t:['بُنِيَ الْإِسْلَامُ عَلَى خَمْسٍ','Islam is built upon five'],
a:['عَنْ أَبِي عَبْدِ الرَّحْمَنِ عَبْدِ اللهِ بْنِ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللهِ ﷺ يَقُولُ: «بُنِيَ الْإِسْلَامُ عَلَى خَمْسٍ: شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللهِ، وَإِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَحَجِّ الْبَيْتِ، وَصَوْمِ رَمَضَانَ».'],
e:['From Abū ʿAbd al-Raḥmān ʿAbdullāh ibn ʿUmar ibn al-Khaṭṭāb, who said: I heard the Messenger of Allah ﷺ say: “Islam is built upon five: testifying that there is no god but Allah and that Muḥammad is the Messenger of Allah, establishing the prayer, giving the zakāh, Hajj to the House, and fasting Ramaḍān.”'],
s:'رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ',v:[['بُنِيَ','was built'],['شَهَادَةٌ','testifying'],['إِقَامٌ','establishing'],['إِيتَاءٌ','giving'],['صَوْمٌ','fasting']]},

{n:4,t:['مَرَاحِلُ خَلْقِ الْإِنْسَانِ','The stages of creation'],
a:['عَنْ أَبِي عَبْدِ الرَّحْمَنِ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: حَدَّثَنَا رَسُولُ اللهِ ﷺ - وَهُوَ الصَّادِقُ الْمَصْدُوقُ -: «إِنَّ أَحَدَكُمْ يُجْمَعُ خَلْقُهُ فِي بَطْنِ أُمِّهِ أَرْبَعِينَ يَوْمًا نُطْفَةً، ثُمَّ يَكُونُ عَلَقَةً مِثْلَ ذَلِكَ، ثُمَّ يَكُونُ مُضْغَةً مِثْلَ ذَلِكَ، ثُمَّ يُرْسَلُ إِلَيْهِ الْمَلَكُ فَيَنْفُخُ فِيهِ الرُّوحَ، وَيُؤْمَرُ بِأَرْبَعِ كَلِمَاتٍ: بِكَتْبِ رِزْقِهِ، وَأَجَلِهِ، وَعَمَلِهِ، وَشَقِيٌّ أَوْ سَعِيدٌ.',
'فَوَاللهِ الَّذِي لَا إِلَهَ غَيْرُهُ، إِنَّ أَحَدَكُمْ لَيَعْمَلُ بِعَمَلِ أَهْلِ الْجَنَّةِ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَهَا إِلَّا ذِرَاعٌ، فَيَسْبِقُ عَلَيْهِ الْكِتَابُ، فَيَعْمَلُ بِعَمَلِ أَهْلِ النَّارِ فَيَدْخُلُهَا. وَإِنَّ أَحَدَكُمْ لَيَعْمَلُ بِعَمَلِ أَهْلِ النَّارِ حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَهَا إِلَّا ذِرَاعٌ، فَيَسْبِقُ عَلَيْهِ الْكِتَابُ، فَيَعْمَلُ بِعَمَلِ أَهْلِ الْجَنَّةِ فَيَدْخُلُهَا».'],
e:['From Abū ʿAbd al-Raḥmān ʿAbdullāh ibn Masʿūd, who said: The Messenger of Allah ﷺ — the truthful, the one believed — told us: “The creation of each of you is gathered in his mother’s womb for forty days as a drop, then it becomes a clinging clot for the same, then a lump of flesh for the same. Then the angel is sent to him and breathes the soul into him, and he is commanded with four things: to write down his provision, his lifespan, his deeds, and whether he will be wretched or happy.',
'By Allah, besides whom there is no god, one of you may do the deeds of the people of Paradise until there is only an arm’s length between him and it, then what is written overtakes him and he does the deeds of the people of the Fire and enters it. And one of you may do the deeds of the people of the Fire until there is only an arm’s length between him and it, then what is written overtakes him and he does the deeds of the people of Paradise and enters it.”'],
s:'رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ',v:[['الصَّادِقُ','the truthful'],['الْمَصْدُوقُ','the one believed'],['نُطْفَةٌ','drop'],['عَلَقَةٌ','clinging clot'],['مُضْغَةٌ','lump of flesh'],['يَنْفُخُ','he breathes'],['أَجَلٌ','lifespan'],['شَقِيٌّ','wretched'],['ذِرَاعٌ','arm’s length'],['فَيَسْبِقُ','then it overtakes']]},

{n:5,t:['مَنْ أَحْدَثَ فِي أَمْرِنَا','Rejecting innovation'],
a:['عَنْ أُمِّ الْمُؤْمِنِينَ أُمِّ عَبْدِ اللهِ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ ﷺ: «مَنْ أَحْدَثَ فِي أَمْرِنَا هَذَا مَا لَيْسَ مِنْهُ فَهُوَ رَدٌّ».','وَفِي رِوَايَةٍ لِمُسْلِمٍ: «مَنْ عَمِلَ عَمَلًا لَيْسَ عَلَيْهِ أَمْرُنَا فَهُوَ رَدٌّ».'],
e:['From the Mother of the Believers, Umm ʿAbdillāh ʿĀʾishah, who said: The Messenger of Allah ﷺ said: “Whoever introduces into this affair of ours something that is not from it, it is rejected.”','In a narration of Muslim: “Whoever does a deed that is not in accordance with our affair, it is rejected.”'],
s:'رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ',v:[['أَحْدَثَ','he introduced (something new)'],['أَمْرُنَا','our affair (the religion)'],['رَدٌّ','rejected']]},

{n:6,t:['الْحَلَالُ بَيِّنٌ وَالْحَرَامُ بَيِّنٌ','The lawful is clear and the unlawful is clear'],
a:['عَنْ أَبِي عَبْدِ اللهِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللهِ ﷺ يَقُولُ: «إِنَّ الْحَلَالَ بَيِّنٌ، وَإِنَّ الْحَرَامَ بَيِّنٌ، وَبَيْنَهُمَا أُمُورٌ مُشْتَبِهَاتٌ لَا يَعْلَمُهُنَّ كَثِيرٌ مِنَ النَّاسِ، فَمَنِ اتَّقَى الشُّبُهَاتِ فَقَدِ اسْتَبْرَأَ لِدِينِهِ وَعِرْضِهِ، وَمَنْ وَقَعَ فِي الشُّبُهَاتِ وَقَعَ فِي الْحَرَامِ، كَالرَّاعِي يَرْعَى حَوْلَ الْحِمَى يُوشِكُ أَنْ يَرْتَعَ فِيهِ.',
'أَلَا وَإِنَّ لِكُلِّ مَلِكٍ حِمًى، أَلَا وَإِنَّ حِمَى اللهِ مَحَارِمُهُ، أَلَا وَإِنَّ فِي الْجَسَدِ مُضْغَةً إِذَا صَلَحَتْ صَلَحَ الْجَسَدُ كُلُّهُ، وَإِذَا فَسَدَتْ فَسَدَ الْجَسَدُ كُلُّهُ، أَلَا وَهِيَ الْقَلْبُ».'],
e:['From Abū ʿAbdillāh al-Nuʿmān ibn Bashīr, who said: I heard the Messenger of Allah ﷺ say: “The lawful is clear and the unlawful is clear, and between them are doubtful matters that many people do not know. Whoever guards against the doubtful matters has protected his religion and his honour, and whoever falls into the doubtful matters falls into the unlawful — like a shepherd grazing around a protected pasture, about to graze in it.',
'Indeed every king has a protected pasture, and indeed Allah’s protected pasture is what He has forbidden. Indeed in the body there is a lump of flesh: if it is sound the whole body is sound, and if it is corrupt the whole body is corrupt. Indeed, it is the heart.”'],
s:'رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ',v:[['بَيِّنٌ','clear'],['مُشْتَبِهَاتٌ','doubtful, unclear'],['اتَّقَى','he guarded against'],['الشُّبُهَاتُ','doubtful matters'],['اسْتَبْرَأَ','he kept clear, protected'],['عِرْضٌ','honour'],['الرَّاعِي','the shepherd'],['الْحِمَى','protected pasture'],['يُوشِكُ','he is about to'],['يَرْتَعَ','(that) he grazes'],['مَحَارِمُهُ','what He has forbidden'],['صَلَحَتْ','it is sound']]},

{n:7,t:['الدِّينُ النَّصِيحَةُ','The religion is sincerity'],
a:['عَنْ أَبِي رُقَيَّةَ تَمِيمِ بْنِ أَوْسٍ الدَّارِيِّ رَضِيَ اللهُ عَنْهُ أَنَّ النَّبِيَّ ﷺ قَالَ: «الدِّينُ النَّصِيحَةُ». قُلْنَا: لِمَنْ؟ قَالَ: «لِلّٰهِ، وَلِكِتَابِهِ، وَلِرَسُولِهِ، وَلِأَئِمَّةِ الْمُسْلِمِينَ وَعَامَّتِهِمْ».'],
e:['From Abū Ruqayyah Tamīm ibn Aws al-Dārī that the Prophet ﷺ said: “The religion is sincerity (naṣīḥah).” We said: “To whom?” He said: “To Allah, His Book, His Messenger, the leaders of the Muslims and their common folk.”'],
s:'رَوَاهُ مُسْلِمٌ',v:[['النَّصِيحَةُ','sincerity, sincere goodwill'],['أَئِمَّةٌ','leaders'],['عَامَّتُهُمْ','their common people']]},

{n:8,t:['حُرْمَةُ الْمُسْلِمِ','The sanctity of a Muslim'],
a:['عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا أَنَّ رَسُولَ اللهِ ﷺ قَالَ: «أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَشْهَدُوا أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللهِ، وَيُقِيمُوا الصَّلَاةَ، وَيُؤْتُوا الزَّكَاةَ، فَإِذَا فَعَلُوا ذَلِكَ عَصَمُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلَّا بِحَقِّ الْإِسْلَامِ، وَحِسَابُهُمْ عَلَى اللهِ تَعَالَى».'],
e:['From Ibn ʿUmar that the Messenger of Allah ﷺ said: “I have been commanded to fight the people until they testify that there is no god but Allah and that Muḥammad is the Messenger of Allah, establish the prayer and give the zakāh. If they do that, they have protected their blood and their wealth from me, except by the right of Islam, and their reckoning is with Allah the Exalted.”'],
s:'رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ',v:[['أُمِرْتُ','I have been commanded'],['أُقَاتِلَ','(that) I fight'],['عَصَمُوا','they have protected'],['دِمَاءَهُمْ','their blood'],['حِسَابُهُمْ','their reckoning']]},

{n:9,t:['مَا نَهَيْتُكُمْ عَنْهُ فَاجْتَنِبُوهُ','What I have forbidden you, avoid'],
a:['عَنْ أَبِي هُرَيْرَةَ عَبْدِ الرَّحْمَنِ بْنِ صَخْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ ﷺ يَقُولُ: «مَا نَهَيْتُكُمْ عَنْهُ فَاجْتَنِبُوهُ، وَمَا أَمَرْتُكُمْ بِهِ فَأْتُوا مِنْهُ مَا اسْتَطَعْتُمْ، فَإِنَّمَا أَهْلَكَ الَّذِينَ مِنْ قَبْلِكُمْ كَثْرَةُ مَسَائِلِهِمْ وَاخْتِلَافُهُمْ عَلَى أَنْبِيَائِهِمْ».'],
e:['From Abū Hurayrah ʿAbd al-Raḥmān ibn Ṣakhr, who said: I heard the Messenger of Allah ﷺ say: “What I have forbidden you, avoid it; and what I have commanded you, do as much of it as you are able. Those before you were destroyed only by their excessive questioning and their disagreeing with their prophets.”'],
s:'رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ',v:[['نَهَيْتُكُمْ','I forbade you'],['فَاجْتَنِبُوهُ','then avoid it'],['فَأْتُوا','then do'],['أَهْلَكَ','destroyed'],['مَسَائِلُ','questions'],['اخْتِلَافُهُمْ','their disagreeing']]},

{n:10,t:['إِنَّ اللهَ طَيِّبٌ','Allah is good'],
a:['عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ ﷺ: «إِنَّ اللهَ تَعَالَى طَيِّبٌ لَا يَقْبَلُ إِلَّا طَيِّبًا، وَإِنَّ اللهَ أَمَرَ الْمُؤْمِنِينَ بِمَا أَمَرَ بِهِ الْمُرْسَلِينَ، فَقَالَ تَعَالَى: ﴿يَا أَيُّهَا الرُّسُلُ كُلُوا مِنَ الطَّيِّبَاتِ وَاعْمَلُوا صَالِحًا﴾، وَقَالَ تَعَالَى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا كُلُوا مِنْ طَيِّبَاتِ مَا رَزَقْنَاكُمْ﴾».',
'ثُمَّ ذَكَرَ الرَّجُلَ يُطِيلُ السَّفَرَ أَشْعَثَ أَغْبَرَ يَمُدُّ يَدَيْهِ إِلَى السَّمَاءِ: يَا رَبِّ يَا رَبِّ، وَمَطْعَمُهُ حَرَامٌ، وَمَشْرَبُهُ حَرَامٌ، وَمَلْبَسُهُ حَرَامٌ، وَغُذِيَ بِالْحَرَامِ، فَأَنَّى يُسْتَجَابُ لِذَلِكَ؟'],
e:['From Abū Hurayrah, who said: The Messenger of Allah ﷺ said: “Allah the Exalted is good and accepts only what is good. Allah has commanded the believers with what He commanded the messengers. He said: ‘O messengers, eat from the good things and do righteous deeds,’ and He said: ‘O you who believe, eat from the good things We have provided you.’”',
'Then he mentioned a man who travels far, dishevelled and dusty, stretching his hands to the sky: “O Lord, O Lord!” — while his food is unlawful, his drink is unlawful, his clothing is unlawful and he has been nourished with the unlawful. So how can he be answered?'],
s:'رَوَاهُ مُسْلِمٌ',v:[['طَيِّبٌ','good, pure'],['يَقْبَلُ','He accepts'],['الطَّيِّبَاتُ','good things'],['يُطِيلُ','he prolongs'],['أَشْعَثَ','dishevelled'],['أَغْبَرَ','dusty'],['مَطْعَمُهُ','his food'],['غُذِيَ','he was nourished'],['فَأَنَّى','so how'],['يُسْتَجَابُ','is answered']]},

{n:11,t:['دَعْ مَا يَرِيبُكَ','Leave what makes you doubt'],
a:['عَنْ أَبِي مُحَمَّدٍ الْحَسَنِ بْنِ عَلِيِّ بْنِ أَبِي طَالِبٍ سِبْطِ رَسُولِ اللهِ ﷺ وَرَيْحَانَتِهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: حَفِظْتُ مِنْ رَسُولِ اللهِ ﷺ: «دَعْ مَا يَرِيبُكَ إِلَى مَا لَا يَرِيبُكَ».'],
e:['From Abū Muḥammad al-Ḥasan ibn ʿAlī ibn Abī Ṭālib, the grandson of the Messenger of Allah ﷺ and his delight, who said: I memorised from the Messenger of Allah ﷺ: “Leave what makes you doubt for what does not make you doubt.”'],
s:'رَوَاهُ التِّرْمِذِيُّ وَالنَّسَائِيُّ، وَقَالَ التِّرْمِذِيُّ: حَدِيثٌ حَسَنٌ صَحِيحٌ',v:[['سِبْطٌ','grandson'],['رَيْحَانَتُهُ','his sweet basil (his delight)'],['حَفِظْتُ','I memorised'],['دَعْ','leave'],['يَرِيبُكَ','makes you doubt']]},

{n:12,t:['تَرْكُ مَا لَا يَعْنِي','Leaving what does not concern you'],
a:['عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ ﷺ: «مِنْ حُسْنِ إِسْلَامِ الْمَرْءِ تَرْكُهُ مَا لَا يَعْنِيهِ».'],
e:['From Abū Hurayrah, who said: The Messenger of Allah ﷺ said: “Part of the excellence of a person’s Islam is his leaving what does not concern him.”'],
s:'حَدِيثٌ حَسَنٌ، رَوَاهُ التِّرْمِذِيُّ وَغَيْرُهُ هَكَذَا',v:[['حُسْنٌ','excellence'],['الْمَرْءُ','a person'],['تَرْكُهُ','his leaving'],['يَعْنِيهِ','concerns him']]},

{n:13,t:['يُحِبُّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ','Loving for your brother what you love for yourself'],
a:['عَنْ أَبِي حَمْزَةَ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ خَادِمِ رَسُولِ اللهِ ﷺ عَنِ النَّبِيِّ ﷺ قَالَ: «لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ».'],
e:['From Abū Ḥamzah Anas ibn Mālik, the servant of the Messenger of Allah ﷺ, that the Prophet ﷺ said: “None of you truly believes until he loves for his brother what he loves for himself.”'],
s:'رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ',v:[['خَادِمٌ','servant'],['لَا يُؤْمِنُ','does not (truly) believe'],['يُحِبَّ','he loves']]},

{n:14,t:['حُرْمَةُ دَمِ الْمُسْلِمِ','The inviolability of a Muslim’s blood'],
a:['عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ ﷺ: «لَا يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ إِلَّا بِإِحْدَى ثَلَاثٍ: الثَّيِّبُ الزَّانِي، وَالنَّفْسُ بِالنَّفْسِ، وَالتَّارِكُ لِدِينِهِ الْمُفَارِقُ لِلْجَمَاعَةِ».'],
e:['From Ibn Masʿūd, who said: The Messenger of Allah ﷺ said: “The blood of a Muslim person is not lawful except in one of three cases: the married person who commits adultery, a life for a life, and the one who abandons his religion and separates from the community.”'],
s:'رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ',v:[['لَا يَحِلُّ','is not lawful'],['دَمٌ','blood'],['الثَّيِّبُ','one who has been married'],['النَّفْسُ','the soul, life'],['التَّارِكُ','the one who abandons'],['الْمُفَارِقُ','the one who separates'],['الْجَمَاعَةُ','the community']]},

{n:15,t:['مِنْ خِصَالِ الْإِيمَانِ','From the qualities of faith'],
a:['عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ أَنَّ رَسُولَ اللهِ ﷺ قَالَ: «مَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ، وَمَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ جَارَهُ، وَمَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ».'],
e:['From Abū Hurayrah that the Messenger of Allah ﷺ said: “Whoever believes in Allah and the Last Day, let him speak good or keep silent; whoever believes in Allah and the Last Day, let him honour his neighbour; and whoever believes in Allah and the Last Day, let him honour his guest.”'],
s:'رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ',v:[['فَلْيَقُلْ','let him say'],['لِيَصْمُتْ','let him be silent'],['فَلْيُكْرِمْ','let him honour'],['جَارٌ','neighbour'],['ضَيْفٌ','guest']]},

{n:16,t:['لَا تَغْضَبْ','Do not become angry'],
a:['عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ أَنَّ رَجُلًا قَالَ لِلنَّبِيِّ ﷺ: أَوْصِنِي. قَالَ: «لَا تَغْضَبْ». فَرَدَّدَ مِرَارًا، قَالَ: «لَا تَغْضَبْ».'],
e:['From Abū Hurayrah that a man said to the Prophet ﷺ: “Advise me.” He said: “Do not become angry.” The man repeated his request several times, and he said: “Do not become angry.”'],
s:'رَوَاهُ الْبُخَارِيُّ',v:[['أَوْصِنِي','advise me'],['لَا تَغْضَبْ','do not get angry'],['فَرَدَّدَ','he repeated'],['مِرَارًا','many times']]},

{n:17,t:['الْإِحْسَانُ فِي كُلِّ شَيْءٍ','Excellence in everything'],
a:['عَنْ أَبِي يَعْلَى شَدَّادِ بْنِ أَوْسٍ رَضِيَ اللهُ عَنْهُ عَنْ رَسُولِ اللهِ ﷺ قَالَ: «إِنَّ اللهَ كَتَبَ الْإِحْسَانَ عَلَى كُلِّ شَيْءٍ، فَإِذَا قَتَلْتُمْ فَأَحْسِنُوا الْقِتْلَةَ، وَإِذَا ذَبَحْتُمْ فَأَحْسِنُوا الذِّبْحَةَ، وَلْيُحِدَّ أَحَدُكُمْ شَفْرَتَهُ، وَلْيُرِحْ ذَبِيحَتَهُ».'],
e:['From Abū Yaʿlā Shaddād ibn Aws that the Messenger of Allah ﷺ said: “Allah has prescribed excellence in everything. So when you kill, kill well; and when you slaughter, slaughter well. Let each of you sharpen his blade and spare his animal suffering.”'],
s:'رَوَاهُ مُسْلِمٌ',v:[['كَتَبَ','He prescribed'],['الْإِحْسَانُ','excellence, doing well'],['الْقِتْلَةُ','manner of killing'],['الذِّبْحَةُ','manner of slaughter'],['وَلْيُحِدَّ','and let him sharpen'],['شَفْرَتُهُ','his blade'],['وَلْيُرِحْ','and let him give ease to'],['ذَبِيحَتُهُ','his animal for slaughter']]},

{n:18,t:['اتَّقِ اللهَ حَيْثُمَا كُنْتَ','Fear Allah wherever you are'],
a:['عَنْ أَبِي ذَرٍّ جُنْدَبِ بْنِ جُنَادَةَ وَأَبِي عَبْدِ الرَّحْمَنِ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللهُ عَنْهُمَا عَنْ رَسُولِ اللهِ ﷺ قَالَ: «اتَّقِ اللهَ حَيْثُمَا كُنْتَ، وَأَتْبِعِ السَّيِّئَةَ الْحَسَنَةَ تَمْحُهَا، وَخَالِقِ النَّاسَ بِخُلُقٍ حَسَنٍ».'],
e:['From Abū Dharr Jundub ibn Junādah and Abū ʿAbd al-Raḥmān Muʿādh ibn Jabal that the Messenger of Allah ﷺ said: “Be mindful of Allah wherever you are, follow a bad deed with a good one and it will wipe it out, and treat people with good character.”'],
s:'رَوَاهُ التِّرْمِذِيُّ وَقَالَ: حَدِيثٌ حَسَنٌ، وَفِي بَعْضِ النُّسَخِ: حَسَنٌ صَحِيحٌ',v:[['اتَّقِ','be mindful of, fear'],['حَيْثُمَا','wherever'],['وَأَتْبِعْ','and follow (with)'],['السَّيِّئَةُ','the bad deed'],['تَمْحُهَا','it will wipe it out'],['وَخَالِقْ','and deal with'],['خُلُقٌ','character']]},

{n:19,t:['احْفَظِ اللهَ يَحْفَظْكَ','Be mindful of Allah and He will protect you'],
a:['عَنْ أَبِي الْعَبَّاسِ عَبْدِ اللهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنْتُ خَلْفَ النَّبِيِّ ﷺ يَوْمًا فَقَالَ: «يَا غُلَامُ، إِنِّي أُعَلِّمُكَ كَلِمَاتٍ: احْفَظِ اللهَ يَحْفَظْكَ، احْفَظِ اللهَ تَجِدْهُ تُجَاهَكَ، إِذَا سَأَلْتَ فَاسْأَلِ اللهَ، وَإِذَا اسْتَعَنْتَ فَاسْتَعِنْ بِاللهِ.',
'وَاعْلَمْ أَنَّ الْأُمَّةَ لَوِ اجْتَمَعَتْ عَلَى أَنْ يَنْفَعُوكَ بِشَيْءٍ لَمْ يَنْفَعُوكَ إِلَّا بِشَيْءٍ قَدْ كَتَبَهُ اللهُ لَكَ، وَإِنِ اجْتَمَعُوا عَلَى أَنْ يَضُرُّوكَ بِشَيْءٍ لَمْ يَضُرُّوكَ إِلَّا بِشَيْءٍ قَدْ كَتَبَهُ اللهُ عَلَيْكَ، رُفِعَتِ الْأَقْلَامُ، وَجَفَّتِ الصُّحُفُ».',
'وَفِي رِوَايَةِ غَيْرِ التِّرْمِذِيِّ: «احْفَظِ اللهَ تَجِدْهُ أَمَامَكَ، تَعَرَّفْ إِلَى اللهِ فِي الرَّخَاءِ يَعْرِفْكَ فِي الشِّدَّةِ، وَاعْلَمْ أَنَّ مَا أَخْطَأَكَ لَمْ يَكُنْ لِيُصِيبَكَ، وَمَا أَصَابَكَ لَمْ يَكُنْ لِيُخْطِئَكَ، وَاعْلَمْ أَنَّ النَّصْرَ مَعَ الصَّبْرِ، وَأَنَّ الْفَرَجَ مَعَ الْكَرْبِ، وَأَنَّ مَعَ الْعُسْرِ يُسْرًا».'],
e:['From Abū al-ʿAbbās ʿAbdullāh ibn ʿAbbās, who said: I was behind the Prophet ﷺ one day and he said: “Young man, I will teach you some words: Be mindful of Allah and He will protect you. Be mindful of Allah and you will find Him before you. When you ask, ask Allah; and when you seek help, seek help from Allah.',
'Know that if the whole nation gathered to benefit you with something, they would not benefit you except with something Allah has already written for you; and if they gathered to harm you with something, they would not harm you except with something Allah has already written against you. The pens have been lifted and the pages have dried.”',
'In a narration other than al-Tirmidhī’s: “Be mindful of Allah and you will find Him in front of you. Get to know Allah in times of ease and He will know you in times of hardship. Know that what passed you by was never going to reach you, and what reached you was never going to pass you by. Know that victory comes with patience, relief with distress, and with hardship comes ease.”'],
s:'رَوَاهُ التِّرْمِذِيُّ وَقَالَ: حَدِيثٌ حَسَنٌ صَحِيحٌ',v:[['غُلَامٌ','young boy'],['احْفَظْ','guard, be mindful of'],['تُجَاهَكَ','in front of you'],['اسْتَعَنْتَ','you sought help'],['رُفِعَتْ','were lifted'],['الْأَقْلَامُ','the pens'],['جَفَّتْ','dried'],['الصُّحُفُ','the pages'],['الرَّخَاءُ','ease, prosperity'],['الشِّدَّةُ','hardship'],['الْفَرَجُ','relief'],['الْكَرْبُ','distress']]},

{n:20,t:['الْحَيَاءُ مِنَ الْإِيمَانِ','Modesty'],
a:['عَنْ أَبِي مَسْعُودٍ عُقْبَةَ بْنِ عَمْرٍو الْأَنْصَارِيِّ الْبَدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ ﷺ: «إِنَّ مِمَّا أَدْرَكَ النَّاسُ مِنْ كَلَامِ النُّبُوَّةِ الْأُولَى: إِذَا لَمْ تَسْتَحِ فَاصْنَعْ مَا شِئْتَ».'],
e:['From Abū Masʿūd ʿUqbah ibn ʿAmr al-Anṣārī al-Badrī, who said: The Messenger of Allah ﷺ said: “Among the words people have received from the earliest prophethood is: If you have no shame, then do as you wish.”'],
s:'رَوَاهُ الْبُخَارِيُّ',v:[['أَدْرَكَ','reached, received'],['النُّبُوَّةُ','prophethood'],['الْأُولَى','the first, earliest'],['تَسْتَحِ','you feel shame'],['فَاصْنَعْ','then do']]},

{n:21,t:['قُلْ: آمَنْتُ بِاللهِ ثُمَّ اسْتَقِمْ','Say “I believe in Allah”, then be steadfast'],
a:['عَنْ أَبِي عَمْرٍو - وَقِيلَ: أَبِي عَمْرَةَ - سُفْيَانَ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، قُلْ لِي فِي الْإِسْلَامِ قَوْلًا لَا أَسْأَلُ عَنْهُ أَحَدًا غَيْرَكَ. قَالَ: «قُلْ: آمَنْتُ بِاللهِ، ثُمَّ اسْتَقِمْ».'],
e:['From Abū ʿAmr — it is also said Abū ʿAmrah — Sufyān ibn ʿAbdillāh, who said: I said: “O Messenger of Allah, tell me something about Islam that I will not need to ask anyone else about.” He said: “Say: I believe in Allah, then be steadfast.”'],
s:'رَوَاهُ مُسْلِمٌ',v:[['قَوْلًا','a saying'],['آمَنْتُ','I believe'],['اسْتَقِمْ','be upright, steadfast']]},

{n:22,t:['الطَّرِيقُ إِلَى الْجَنَّةِ','The way to Paradise'],
a:['عَنْ أَبِي عَبْدِ اللهِ جَابِرِ بْنِ عَبْدِ اللهِ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُمَا أَنَّ رَجُلًا سَأَلَ رَسُولَ اللهِ ﷺ فَقَالَ: أَرَأَيْتَ إِذَا صَلَّيْتُ الْمَكْتُوبَاتِ، وَصُمْتُ رَمَضَانَ، وَأَحْلَلْتُ الْحَلَالَ، وَحَرَّمْتُ الْحَرَامَ، وَلَمْ أَزِدْ عَلَى ذَلِكَ شَيْئًا، أَأَدْخُلُ الْجَنَّةَ؟ قَالَ: «نَعَمْ».'],
e:['From Abū ʿAbdillāh Jābir ibn ʿAbdillāh al-Anṣārī that a man asked the Messenger of Allah ﷺ: “Do you think that if I pray the obligatory prayers, fast Ramaḍān, treat the lawful as lawful and the unlawful as unlawful, and do nothing more than that, I will enter Paradise?” He said: “Yes.”'],
s:'رَوَاهُ مُسْلِمٌ',v:[['أَرَأَيْتَ','what do you think?'],['الْمَكْتُوبَاتُ','the obligatory prayers'],['أَحْلَلْتُ','I treated as lawful'],['حَرَّمْتُ','I treated as unlawful'],['أَزِدْ','I add']]},

{n:23,t:['الطُّهُورُ شَطْرُ الْإِيمَانِ','Purity is half of faith'],
a:['عَنْ أَبِي مَالِكٍ الْحَارِثِ بْنِ عَاصِمٍ الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ ﷺ: «الطُّهُورُ شَطْرُ الْإِيمَانِ، وَالْحَمْدُ لِلّٰهِ تَمْلَأُ الْمِيزَانَ، وَسُبْحَانَ اللهِ وَالْحَمْدُ لِلّٰهِ تَمْلَآنِ - أَوْ: تَمْلَأُ - مَا بَيْنَ السَّمَاءِ وَالْأَرْضِ، وَالصَّلَاةُ نُورٌ، وَالصَّدَقَةُ بُرْهَانٌ، وَالصَّبْرُ ضِيَاءٌ، وَالْقُرْآنُ حُجَّةٌ لَكَ أَوْ عَلَيْكَ، كُلُّ النَّاسِ يَغْدُو، فَبَائِعٌ نَفْسَهُ فَمُعْتِقُهَا أَوْ مُوبِقُهَا».'],
e:['From Abū Mālik al-Ḥārith ibn ʿĀṣim al-Ashʿarī, who said: The Messenger of Allah ﷺ said: “Purity is half of faith. Al-ḥamdu lillāh fills the scale, and subḥān Allāh and al-ḥamdu lillāh fill — or: fills — what is between the heavens and the earth. Prayer is light, charity is proof, patience is illumination, and the Qur’an is an argument for you or against you. Every person goes out in the morning and sells himself, either freeing it or ruining it.”'],
s:'رَوَاهُ مُسْلِمٌ',v:[['الطُّهُورُ','purification'],['شَطْرٌ','half'],['تَمْلَأُ','it fills'],['الْمِيزَانُ','the scale'],['بُرْهَانٌ','proof'],['ضِيَاءٌ','radiance'],['حُجَّةٌ','proof, argument'],['يَغْدُو','goes out in the morning'],['بَائِعٌ','selling'],['مُعْتِقُهَا','freeing it'],['مُوبِقُهَا','destroying it']]},

{n:24,t:['تَحْرِيمُ الظُّلْمِ','The prohibition of injustice'],
a:['عَنْ أَبِي ذَرٍّ الْغِفَارِيِّ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ ﷺ فِيمَا يَرْوِيهِ عَنْ رَبِّهِ عَزَّ وَجَلَّ أَنَّهُ قَالَ: «يَا عِبَادِي، إِنِّي حَرَّمْتُ الظُّلْمَ عَلَى نَفْسِي، وَجَعَلْتُهُ بَيْنَكُمْ مُحَرَّمًا، فَلَا تَظَالَمُوا.',
'يَا عِبَادِي، كُلُّكُمْ ضَالٌّ إِلَّا مَنْ هَدَيْتُهُ، فَاسْتَهْدُونِي أَهْدِكُمْ. يَا عِبَادِي، كُلُّكُمْ جَائِعٌ إِلَّا مَنْ أَطْعَمْتُهُ، فَاسْتَطْعِمُونِي أُطْعِمْكُمْ. يَا عِبَادِي، كُلُّكُمْ عَارٍ إِلَّا مَنْ كَسَوْتُهُ، فَاسْتَكْسُونِي أَكْسُكُمْ. يَا عِبَادِي، إِنَّكُمْ تُخْطِئُونَ بِاللَّيْلِ وَالنَّهَارِ، وَأَنَا أَغْفِرُ الذُّنُوبَ جَمِيعًا، فَاسْتَغْفِرُونِي أَغْفِرْ لَكُمْ.',
'يَا عِبَادِي، إِنَّكُمْ لَنْ تَبْلُغُوا ضَرِّي فَتَضُرُّونِي، وَلَنْ تَبْلُغُوا نَفْعِي فَتَنْفَعُونِي. يَا عِبَادِي، لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ كَانُوا عَلَى أَتْقَى قَلْبِ رَجُلٍ وَاحِدٍ مِنْكُمْ، مَا زَادَ ذَلِكَ فِي مُلْكِي شَيْئًا. يَا عِبَادِي، لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ كَانُوا عَلَى أَفْجَرِ قَلْبِ رَجُلٍ وَاحِدٍ مِنْكُمْ، مَا نَقَصَ ذَلِكَ مِنْ مُلْكِي شَيْئًا.',
'يَا عِبَادِي، لَوْ أَنَّ أَوَّلَكُمْ وَآخِرَكُمْ وَإِنْسَكُمْ وَجِنَّكُمْ قَامُوا فِي صَعِيدٍ وَاحِدٍ فَسَأَلُونِي، فَأَعْطَيْتُ كُلَّ وَاحِدٍ مَسْأَلَتَهُ، مَا نَقَصَ ذَلِكَ مِمَّا عِنْدِي إِلَّا كَمَا يَنْقُصُ الْمِخْيَطُ إِذَا أُدْخِلَ الْبَحْرَ.',
'يَا عِبَادِي، إِنَّمَا هِيَ أَعْمَالُكُمْ أُحْصِيهَا لَكُمْ، ثُمَّ أُوَفِّيكُمْ إِيَّاهَا، فَمَنْ وَجَدَ خَيْرًا فَلْيَحْمَدِ اللهَ، وَمَنْ وَجَدَ غَيْرَ ذَلِكَ فَلَا يَلُومَنَّ إِلَّا نَفْسَهُ».'],
e:['From Abū Dharr al-Ghifārī, from the Prophet ﷺ, among what he narrates from his Lord, Mighty and Majestic, that He said: “O My servants, I have forbidden injustice for Myself and made it forbidden among you, so do not wrong one another.',
'O My servants, all of you are astray except those I guide, so seek guidance from Me and I will guide you. O My servants, all of you are hungry except those I feed, so ask Me for food and I will feed you. O My servants, all of you are unclothed except those I clothe, so ask Me for clothing and I will clothe you. O My servants, you sin by night and by day, and I forgive all sins, so seek My forgiveness and I will forgive you.',
'O My servants, you will never be able to harm Me, nor will you ever be able to benefit Me. O My servants, if the first and last of you, the humans and jinn among you, were as pious as the most pious heart of any one of you, that would not add anything to My kingdom. O My servants, if the first and last of you, the humans and jinn among you, were as wicked as the most wicked heart of any one of you, that would not take anything from My kingdom.',
'O My servants, if the first and last of you, the humans and jinn among you, stood on one plain and asked of Me, and I gave each one what he asked, that would not decrease what I have except as a needle decreases the sea when it is dipped into it.',
'O My servants, it is only your deeds that I record for you, then I will repay you in full for them. So whoever finds good, let him praise Allah; and whoever finds otherwise, let him blame no one but himself.”'],
s:'رَوَاهُ مُسْلِمٌ',v:[['الظُّلْمُ','injustice'],['تَظَالَمُوا','wrong one another'],['ضَالٌّ','astray'],['فَاسْتَهْدُونِي','so seek guidance from Me'],['عَارٍ','unclothed'],['كَسَوْتُهُ','I clothed him'],['أَتْقَى','most pious'],['أَفْجَرِ','most wicked'],['صَعِيدٌ','plain, open ground'],['الْمِخْيَطُ','needle'],['أُحْصِيهَا','I count them'],['أُوَفِّيكُمْ','I repay you in full'],['يَلُومَنَّ','let him blame']]},

{n:25,t:['فَضْلُ الذِّكْرِ','The virtue of remembrance'],
a:['عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ أَيْضًا أَنَّ نَاسًا مِنْ أَصْحَابِ رَسُولِ اللهِ ﷺ قَالُوا لِلنَّبِيِّ ﷺ: يَا رَسُولَ اللهِ، ذَهَبَ أَهْلُ الدُّثُورِ بِالْأُجُورِ، يُصَلُّونَ كَمَا نُصَلِّي، وَيَصُومُونَ كَمَا نَصُومُ، وَيَتَصَدَّقُونَ بِفُضُولِ أَمْوَالِهِمْ.',
'قَالَ: «أَوَلَيْسَ قَدْ جَعَلَ اللهُ لَكُمْ مَا تَصَّدَّقُونَ؟ إِنَّ بِكُلِّ تَسْبِيحَةٍ صَدَقَةً، وَكُلِّ تَكْبِيرَةٍ صَدَقَةً، وَكُلِّ تَحْمِيدَةٍ صَدَقَةً، وَكُلِّ تَهْلِيلَةٍ صَدَقَةً، وَأَمْرٌ بِالْمَعْرُوفِ صَدَقَةٌ، وَنَهْيٌ عَنْ مُنْكَرٍ صَدَقَةٌ، وَفِي بُضْعِ أَحَدِكُمْ صَدَقَةٌ».',
'قَالُوا: يَا رَسُولَ اللهِ، أَيَأْتِي أَحَدُنَا شَهْوَتَهُ وَيَكُونُ لَهُ فِيهَا أَجْرٌ؟ قَالَ: «أَرَأَيْتُمْ لَوْ وَضَعَهَا فِي حَرَامٍ أَكَانَ عَلَيْهِ وِزْرٌ؟ فَكَذَلِكَ إِذَا وَضَعَهَا فِي الْحَلَالِ كَانَ لَهُ أَجْرٌ».'],
e:['Also from Abū Dharr that some of the Companions of the Messenger of Allah ﷺ said to the Prophet ﷺ: “O Messenger of Allah, the wealthy have taken all the rewards. They pray as we pray, fast as we fast, and give charity from their surplus wealth.”',
'He said: “Has Allah not given you things to give in charity? Every tasbīḥ is a charity, every takbīr is a charity, every taḥmīd is a charity, every tahlīl is a charity, commanding good is a charity, forbidding evil is a charity, and in the intimacy of one of you with his wife there is charity.”',
'They said: “O Messenger of Allah, does one of us fulfil his desire and get a reward for it?” He said: “Do you not see that if he put it in something unlawful he would bear a sin? Likewise, if he puts it in what is lawful, he has a reward.”'],
s:'رَوَاهُ مُسْلِمٌ',v:[['الدُّثُورُ','great wealth'],['الْأُجُورُ','the rewards'],['فُضُولُ','surplus'],['تَسْبِيحَةٌ','saying subḥān Allāh'],['تَكْبِيرَةٌ','saying Allāhu akbar'],['تَحْمِيدَةٌ','saying al-ḥamdu lillāh'],['تَهْلِيلَةٌ','saying lā ilāha illā Allāh'],['الْمَعْرُوفُ','what is good'],['مُنْكَرٌ','evil'],['شَهْوَتُهُ','his desire'],['وِزْرٌ','sin, burden']]},

{n:26,t:['طُرُقُ الْخَيْرِ','The ways of goodness'],
a:['عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ ﷺ: «كُلُّ سُلَامَى مِنَ النَّاسِ عَلَيْهِ صَدَقَةٌ، كُلَّ يَوْمٍ تَطْلُعُ فِيهِ الشَّمْسُ: تَعْدِلُ بَيْنَ اثْنَيْنِ صَدَقَةٌ، وَتُعِينُ الرَّجُلَ فِي دَابَّتِهِ فَتَحْمِلُهُ عَلَيْهَا أَوْ تَرْفَعُ لَهُ عَلَيْهَا مَتَاعَهُ صَدَقَةٌ، وَالْكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ، وَبِكُلِّ خُطْوَةٍ تَمْشِيهَا إِلَى الصَّلَاةِ صَدَقَةٌ، وَتُمِيطُ الْأَذَى عَنِ الطَّرِيقِ صَدَقَةٌ».'],
e:['From Abū Hurayrah, who said: The Messenger of Allah ﷺ said: “Every joint of a person owes a charity every day the sun rises: judging fairly between two people is a charity; helping a man with his mount, lifting him onto it or lifting his belongings onto it, is a charity; a good word is a charity; every step you take to the prayer is a charity; and removing something harmful from the road is a charity.”'],
s:'رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ',v:[['سُلَامَى','joint, small bone'],['تَعْدِلُ','you judge fairly'],['تُعِينُ','you help'],['دَابَّتُهُ','his riding animal'],['مَتَاعُهُ','his belongings'],['خُطْوَةٌ','a step'],['تُمِيطُ','you remove'],['الْأَذَى','harm']]},

{n:27,t:['الْبِرُّ حُسْنُ الْخُلُقِ','Righteousness is good character'],
a:['عَنِ النَّوَّاسِ بْنِ سَمْعَانَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ ﷺ قَالَ: «الْبِرُّ حُسْنُ الْخُلُقِ، وَالْإِثْمُ مَا حَاكَ فِي صَدْرِكَ وَكَرِهْتَ أَنْ يَطَّلِعَ عَلَيْهِ النَّاسُ». رَوَاهُ مُسْلِمٌ.',
'وَعَنْ وَابِصَةَ بْنِ مَعْبَدٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ رَسُولَ اللهِ ﷺ فَقَالَ: «جِئْتَ تَسْأَلُ عَنِ الْبِرِّ؟» قُلْتُ: نَعَمْ. فَقَالَ: «اسْتَفْتِ قَلْبَكَ، الْبِرُّ مَا اطْمَأَنَّتْ إِلَيْهِ النَّفْسُ وَاطْمَأَنَّ إِلَيْهِ الْقَلْبُ، وَالْإِثْمُ مَا حَاكَ فِي النَّفْسِ وَتَرَدَّدَ فِي الصَّدْرِ، وَإِنْ أَفْتَاكَ النَّاسُ وَأَفْتَوْكَ». حَدِيثٌ حَسَنٌ، رُوِّينَاهُ فِي مُسْنَدَيِ الْإِمَامَيْنِ أَحْمَدَ بْنِ حَنْبَلٍ وَالدَّارِمِيِّ بِإِسْنَادٍ حَسَنٍ.'],
e:['From al-Nawwās ibn Samʿān that the Prophet ﷺ said: “Righteousness is good character, and sin is what wavers in your chest and you would hate people to find out about.” (Muslim)',
'And from Wābiṣah ibn Maʿbad, who said: I came to the Messenger of Allah ﷺ and he said: “You have come to ask about righteousness?” I said: “Yes.” He said: “Consult your heart. Righteousness is what the soul and the heart feel at peace with, and sin is what wavers in the soul and hesitates in the chest, even if people give you rulings and give you rulings.” (A ḥasan ḥadīth, narrated in the Musnads of Aḥmad and al-Dārimī)'],
s:'رَوَاهُ مُسْلِمٌ؛ وَأَحْمَدُ وَالدَّارِمِيُّ',v:[['الْبِرُّ','righteousness'],['الْإِثْمُ','sin'],['حَاكَ','it wavered, stirred'],['يَطَّلِعَ','(that) he finds out'],['اسْتَفْتِ','seek a ruling from'],['اطْمَأَنَّتْ','it felt at peace'],['تَرَدَّدَ','it hesitated'],['أَفْتَاكَ','he gave you a ruling']]},

{n:28,t:['لُزُومُ السُّنَّةِ','Holding to the Sunnah'],
a:['عَنْ أَبِي نَجِيحٍ الْعِرْبَاضِ بْنِ سَارِيَةَ رَضِيَ اللهُ عَنْهُ قَالَ: وَعَظَنَا رَسُولُ اللهِ ﷺ مَوْعِظَةً وَجِلَتْ مِنْهَا الْقُلُوبُ، وَذَرَفَتْ مِنْهَا الْعُيُونُ، فَقُلْنَا: يَا رَسُولَ اللهِ، كَأَنَّهَا مَوْعِظَةُ مُوَدِّعٍ فَأَوْصِنَا.',
'قَالَ: «أُوصِيكُمْ بِتَقْوَى اللهِ عَزَّ وَجَلَّ، وَالسَّمْعِ وَالطَّاعَةِ وَإِنْ تَأَمَّرَ عَلَيْكُمْ عَبْدٌ، فَإِنَّهُ مَنْ يَعِشْ مِنْكُمْ فَسَيَرَى اخْتِلَافًا كَثِيرًا، فَعَلَيْكُمْ بِسُنَّتِي وَسُنَّةِ الْخُلَفَاءِ الرَّاشِدِينَ الْمَهْدِيِّينَ، عَضُّوا عَلَيْهَا بِالنَّوَاجِذِ، وَإِيَّاكُمْ وَمُحْدَثَاتِ الْأُمُورِ، فَإِنَّ كُلَّ بِدْعَةٍ ضَلَالَةٌ».'],
e:['From Abū Najīḥ al-ʿIrbāḍ ibn Sāriyah, who said: The Messenger of Allah ﷺ gave us an admonition that made our hearts tremble and our eyes shed tears. We said: “O Messenger of Allah, it is as though this is a farewell admonition, so advise us.”',
'He said: “I advise you to be mindful of Allah, Mighty and Majestic, and to listen and obey even if a slave is made your leader. Whoever of you lives will see much disagreement, so hold to my Sunnah and the Sunnah of the rightly guided caliphs. Bite onto it with your molar teeth, and beware of newly invented matters, for every innovation is misguidance.”'],
s:'رَوَاهُ أَبُو دَاوُدَ وَالتِّرْمِذِيُّ وَقَالَ: حَدِيثٌ حَسَنٌ صَحِيحٌ',v:[['وَعَظَنَا','he admonished us'],['وَجِلَتْ','they trembled with fear'],['ذَرَفَتْ','they shed tears'],['مُوَدِّعٍ','one bidding farewell'],['تَأَمَّرَ','he became leader'],['الرَّاشِدِينَ','rightly guided'],['عَضُّوا','bite'],['النَّوَاجِذُ','molar teeth'],['مُحْدَثَاتُ','newly invented matters'],['بِدْعَةٌ','innovation'],['ضَلَالَةٌ','misguidance']]},

{n:29,t:['أَبْوَابُ الْخَيْرِ','The gates of goodness'],
a:['عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، أَخْبِرْنِي بِعَمَلٍ يُدْخِلُنِي الْجَنَّةَ وَيُبَاعِدُنِي مِنَ النَّارِ. قَالَ: «لَقَدْ سَأَلْتَ عَنْ عَظِيمٍ، وَإِنَّهُ لَيَسِيرٌ عَلَى مَنْ يَسَّرَهُ اللهُ عَلَيْهِ: تَعْبُدُ اللهَ لَا تُشْرِكُ بِهِ شَيْئًا، وَتُقِيمُ الصَّلَاةَ، وَتُؤْتِي الزَّكَاةَ، وَتَصُومُ رَمَضَانَ، وَتَحُجُّ الْبَيْتَ».',
'ثُمَّ قَالَ: «أَلَا أَدُلُّكَ عَلَى أَبْوَابِ الْخَيْرِ؟ الصَّوْمُ جُنَّةٌ، وَالصَّدَقَةُ تُطْفِئُ الْخَطِيئَةَ كَمَا يُطْفِئُ الْمَاءُ النَّارَ، وَصَلَاةُ الرَّجُلِ فِي جَوْفِ اللَّيْلِ»، ثُمَّ تَلَا: ﴿تَتَجَافَى جُنُوبُهُمْ عَنِ الْمَضَاجِعِ﴾ حَتَّى بَلَغَ ﴿يَعْمَلُونَ﴾.',
'ثُمَّ قَالَ: «أَلَا أُخْبِرُكَ بِرَأْسِ الْأَمْرِ وَعَمُودِهِ وَذِرْوَةِ سَنَامِهِ؟» قُلْتُ: بَلَى يَا رَسُولَ اللهِ. قَالَ: «رَأْسُ الْأَمْرِ الْإِسْلَامُ، وَعَمُودُهُ الصَّلَاةُ، وَذِرْوَةُ سَنَامِهِ الْجِهَادُ».',
'ثُمَّ قَالَ: «أَلَا أُخْبِرُكَ بِمِلَاكِ ذَلِكَ كُلِّهِ؟» قُلْتُ: بَلَى يَا رَسُولَ اللهِ. فَأَخَذَ بِلِسَانِهِ وَقَالَ: «كُفَّ عَلَيْكَ هَذَا». قُلْتُ: يَا نَبِيَّ اللهِ، وَإِنَّا لَمُؤَاخَذُونَ بِمَا نَتَكَلَّمُ بِهِ؟ فَقَالَ: «ثَكِلَتْكَ أُمُّكَ، وَهَلْ يَكُبُّ النَّاسَ فِي النَّارِ عَلَى وُجُوهِهِمْ - أَوْ قَالَ: عَلَى مَنَاخِرِهِمْ - إِلَّا حَصَائِدُ أَلْسِنَتِهِمْ؟!»'],
e:['From Muʿādh ibn Jabal, who said: I said: “O Messenger of Allah, tell me of a deed that will enter me into Paradise and keep me far from the Fire.” He said: “You have asked about something great, yet it is easy for whoever Allah makes it easy for: worship Allah without associating anything with Him, establish the prayer, give the zakāh, fast Ramaḍān and perform Hajj to the House.”',
'Then he said: “Shall I not guide you to the gates of goodness? Fasting is a shield; charity extinguishes sin as water extinguishes fire; and a man’s prayer in the depth of the night.” Then he recited: “Their sides forsake their beds…” until he reached “…they used to do.”',
'Then he said: “Shall I not tell you of the head of the matter, its pillar and its highest peak?” I said: “Yes, O Messenger of Allah.” He said: “The head of the matter is Islam, its pillar is the prayer, and its highest peak is jihād.”',
'Then he said: “Shall I not tell you what holds all of that together?” I said: “Yes, O Messenger of Allah.” He took hold of his tongue and said: “Restrain this.” I said: “O Prophet of Allah, will we be held to account for what we say?” He said: “May your mother lose you! Is there anything that throws people into the Fire on their faces — or he said, on their noses — except the harvest of their tongues?”'],
s:'رَوَاهُ التِّرْمِذِيُّ وَقَالَ: حَدِيثٌ حَسَنٌ صَحِيحٌ',v:[['يُبَاعِدُنِي','keeps me far'],['يَسِيرٌ','easy'],['جُنَّةٌ','shield'],['تُطْفِئُ','extinguishes'],['جَوْفُ اللَّيْلِ','the depth of the night'],['تَتَجَافَى','they forsake'],['الْمَضَاجِعُ','beds'],['عَمُودٌ','pillar'],['ذِرْوَةُ سَنَامِهِ','its highest peak'],['مِلَاكٌ','what holds together'],['كُفَّ','restrain'],['مُؤَاخَذُونَ','held to account'],['ثَكِلَتْكَ','may (your mother) lose you'],['يَكُبُّ','throws face-down'],['مَنَاخِرُ','noses'],['حَصَائِدُ','harvests']]},

{n:30,t:['حُقُوقُ اللهِ','The limits set by Allah'],
a:['عَنْ أَبِي ثَعْلَبَةَ الْخُشَنِيِّ جُرْثُومِ بْنِ نَاشِرٍ رَضِيَ اللهُ عَنْهُ عَنْ رَسُولِ اللهِ ﷺ قَالَ: «إِنَّ اللهَ تَعَالَى فَرَضَ فَرَائِضَ فَلَا تُضَيِّعُوهَا، وَحَدَّ حُدُودًا فَلَا تَعْتَدُوهَا، وَحَرَّمَ أَشْيَاءَ فَلَا تَنْتَهِكُوهَا، وَسَكَتَ عَنْ أَشْيَاءَ رَحْمَةً لَكُمْ غَيْرَ نِسْيَانٍ فَلَا تَبْحَثُوا عَنْهَا».'],
e:['From Abū Thaʿlabah al-Khushanī Jurthūm ibn Nāshir that the Messenger of Allah ﷺ said: “Allah the Exalted has laid down obligations, so do not neglect them; He has set limits, so do not overstep them; He has forbidden things, so do not violate them; and He has been silent about things, out of mercy for you and not out of forgetfulness, so do not go searching into them.”'],
s:'حَدِيثٌ حَسَنٌ، رَوَاهُ الدَّارَقُطْنِيُّ وَغَيْرُهُ',v:[['فَرَضَ','He made obligatory'],['فَرَائِضُ','obligations'],['تُضَيِّعُوهَا','neglect them'],['حُدُودٌ','limits'],['تَعْتَدُوهَا','overstep them'],['تَنْتَهِكُوهَا','violate them'],['سَكَتَ','He was silent'],['تَبْحَثُوا','search into']]},

{n:31,t:['ازْهَدْ فِي الدُّنْيَا','Detach yourself from the world'],
a:['عَنْ أَبِي الْعَبَّاسِ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ ﷺ فَقَالَ: يَا رَسُولَ اللهِ، دُلَّنِي عَلَى عَمَلٍ إِذَا عَمِلْتُهُ أَحَبَّنِيَ اللهُ وَأَحَبَّنِيَ النَّاسُ. فَقَالَ: «ازْهَدْ فِي الدُّنْيَا يُحِبَّكَ اللهُ، وَازْهَدْ فِيمَا عِنْدَ النَّاسِ يُحِبَّكَ النَّاسُ».'],
e:['From Abū al-ʿAbbās Sahl ibn Saʿd al-Sāʿidī, who said: A man came to the Prophet ﷺ and said: “O Messenger of Allah, guide me to a deed which, if I do it, Allah will love me and people will love me.” He said: “Be detached from the world and Allah will love you, and be detached from what people have and people will love you.”'],
s:'حَدِيثٌ حَسَنٌ، رَوَاهُ ابْنُ مَاجَهْ وَغَيْرُهُ بِأَسَانِيدَ حَسَنَةٍ',v:[['دُلَّنِي','guide me'],['ازْهَدْ','be detached'],['يُحِبَّكَ','He will love you']]},

{n:32,t:['لَا ضَرَرَ وَلَا ضِرَارَ','No harm and no reciprocating harm'],
a:['عَنْ أَبِي سَعِيدٍ سَعْدِ بْنِ مَالِكِ بْنِ سِنَانٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ أَنَّ رَسُولَ اللهِ ﷺ قَالَ: «لَا ضَرَرَ وَلَا ضِرَارَ».'],
e:['From Abū Saʿīd Saʿd ibn Mālik ibn Sinān al-Khudrī that the Messenger of Allah ﷺ said: “There is to be no harm and no reciprocating harm.”'],
s:'حَدِيثٌ حَسَنٌ، رَوَاهُ ابْنُ مَاجَهْ وَالدَّارَقُطْنِيُّ وَغَيْرُهُمَا مُسْنَدًا، وَرَوَاهُ مَالِكٌ فِي الْمُوَطَّإِ مُرْسَلًا، وَلَهُ طُرُقٌ يُقَوِّي بَعْضُهَا بَعْضًا',v:[['ضَرَرٌ','harm'],['ضِرَارٌ','harming in return']]},

{n:33,t:['الْبَيِّنَةُ عَلَى الْمُدَّعِي','The burden of proof is on the claimant'],
a:['عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا أَنَّ رَسُولَ اللهِ ﷺ قَالَ: «لَوْ يُعْطَى النَّاسُ بِدَعْوَاهُمْ لَادَّعَى رِجَالٌ أَمْوَالَ قَوْمٍ وَدِمَاءَهُمْ، لَكِنِ الْبَيِّنَةُ عَلَى الْمُدَّعِي، وَالْيَمِينُ عَلَى مَنْ أَنْكَرَ».'],
e:['From Ibn ʿAbbās that the Messenger of Allah ﷺ said: “If people were given whatever they claimed, men would claim the wealth and blood of others. Rather, the proof is upon the claimant, and the oath is upon the one who denies.”'],
s:'حَدِيثٌ حَسَنٌ، رَوَاهُ الْبَيْهَقِيُّ وَغَيْرُهُ هَكَذَا، وَبَعْضُهُ فِي الصَّحِيحَيْنِ',v:[['دَعْوَاهُمْ','their claims'],['لَادَّعَى','would claim'],['الْبَيِّنَةُ','clear proof'],['الْمُدَّعِي','the claimant'],['الْيَمِينُ','the oath'],['أَنْكَرَ','he denied']]},

{n:34,t:['تَغْيِيرُ الْمُنْكَرِ','Changing what is wrong'],
a:['عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ ﷺ يَقُولُ: «مَنْ رَأَى مِنْكُمْ مُنْكَرًا فَلْيُغَيِّرْهُ بِيَدِهِ، فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ، فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ، وَذَلِكَ أَضْعَفُ الْإِيمَانِ».'],
e:['From Abū Saʿīd al-Khudrī, who said: I heard the Messenger of Allah ﷺ say: “Whoever of you sees something wrong, let him change it with his hand; if he cannot, then with his tongue; and if he cannot, then with his heart — and that is the weakest of faith.”'],
s:'رَوَاهُ مُسْلِمٌ',v:[['مُنْكَرًا','something wrong, evil'],['فَلْيُغَيِّرْهُ','let him change it'],['يَسْتَطِعْ','he is able'],['أَضْعَفُ','the weakest']]},

{n:35,t:['أُخُوَّةُ الْإِسْلَامِ','The brotherhood of Islam'],
a:['عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ ﷺ: «لَا تَحَاسَدُوا، وَلَا تَنَاجَشُوا، وَلَا تَبَاغَضُوا، وَلَا تَدَابَرُوا، وَلَا يَبِعْ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ، وَكُونُوا عِبَادَ اللهِ إِخْوَانًا.',
'الْمُسْلِمُ أَخُو الْمُسْلِمِ، لَا يَظْلِمُهُ، وَلَا يَخْذُلُهُ، وَلَا يَكْذِبُهُ، وَلَا يَحْقِرُهُ، التَّقْوَى هَاهُنَا - وَيُشِيرُ إِلَى صَدْرِهِ ثَلَاثَ مَرَّاتٍ - بِحَسْبِ امْرِئٍ مِنَ الشَّرِّ أَنْ يَحْقِرَ أَخَاهُ الْمُسْلِمَ، كُلُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ حَرَامٌ: دَمُهُ وَمَالُهُ وَعِرْضُهُ».'],
e:['From Abū Hurayrah, who said: The Messenger of Allah ﷺ said: “Do not envy one another, do not inflate prices against one another, do not hate one another, do not turn your backs on one another, and do not undercut one another in trade. Be, O servants of Allah, brothers.',
'A Muslim is the brother of a Muslim: he does not wrong him, abandon him, lie to him or look down on him. Taqwā is here — and he pointed to his chest three times. It is evil enough for a person to look down on his Muslim brother. All of a Muslim is sacred to another Muslim: his blood, his wealth and his honour.”'],
s:'رَوَاهُ مُسْلِمٌ',v:[['تَحَاسَدُوا','envy one another'],['تَنَاجَشُوا','bid up prices deceptively'],['تَبَاغَضُوا','hate one another'],['تَدَابَرُوا','turn your backs on one another'],['يَخْذُلُهُ','he abandons him'],['يَحْقِرُهُ','he looks down on him'],['بِحَسْبِ','it is enough for'],['عِرْضُهُ','his honour']]},

{n:36,t:['قَضَاءُ حَوَائِجِ الْمُسْلِمِينَ','Relieving the needs of Muslims'],
a:['عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ ﷺ قَالَ: «مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ، وَمَنْ يَسَّرَ عَلَى مُعْسِرٍ يَسَّرَ اللهُ عَلَيْهِ فِي الدُّنْيَا وَالْآخِرَةِ، وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللهُ فِي الدُّنْيَا وَالْآخِرَةِ، وَاللهُ فِي عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِي عَوْنِ أَخِيهِ.',
'وَمَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا سَهَّلَ اللهُ لَهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ، وَمَا اجْتَمَعَ قَوْمٌ فِي بَيْتٍ مِنْ بُيُوتِ اللهِ يَتْلُونَ كِتَابَ اللهِ وَيَتَدَارَسُونَهُ بَيْنَهُمْ إِلَّا نَزَلَتْ عَلَيْهِمُ السَّكِينَةُ، وَغَشِيَتْهُمُ الرَّحْمَةُ، وَحَفَّتْهُمُ الْمَلَائِكَةُ، وَذَكَرَهُمُ اللهُ فِيمَنْ عِنْدَهُ، وَمَنْ بَطَّأَ بِهِ عَمَلُهُ لَمْ يُسْرِعْ بِهِ نَسَبُهُ».'],
e:['From Abū Hurayrah that the Prophet ﷺ said: “Whoever relieves a believer of one of the distresses of this world, Allah will relieve him of one of the distresses of the Day of Resurrection. Whoever makes things easy for someone in difficulty, Allah will make things easy for him in this world and the next. Whoever covers (the faults of) a Muslim, Allah will cover him in this world and the next. Allah helps His servant as long as the servant helps his brother.',
'Whoever travels a path seeking knowledge, Allah makes easy for him by it a path to Paradise. No people gather in one of the houses of Allah, reciting the Book of Allah and studying it together, except that tranquillity descends upon them, mercy covers them, the angels surround them, and Allah mentions them among those with Him. Whoever is slowed down by his deeds will not be hastened forward by his lineage.”'],
s:'رَوَاهُ مُسْلِمٌ بِهَذَا اللَّفْظِ',v:[['نَفَّسَ','he relieved'],['كُرْبَةٌ','a distress'],['يَسَّرَ','he made easy'],['مُعْسِرٌ','one in difficulty'],['سَتَرَ','he covered'],['عَوْنٌ','help'],['يَلْتَمِسُ','he seeks'],['يَتَدَارَسُونَهُ','they study it together'],['السَّكِينَةُ','tranquillity'],['غَشِيَتْهُمْ','covered them'],['حَفَّتْهُمْ','surrounded them'],['بَطَّأَ','slowed down'],['نَسَبُهُ','his lineage']]},

{n:37,t:['فَضْلُ اللهِ وَرَحْمَتُهُ','Allah’s grace and mercy'],
a:['عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا عَنْ رَسُولِ اللهِ ﷺ فِيمَا يَرْوِيهِ عَنْ رَبِّهِ تَبَارَكَ وَتَعَالَى قَالَ: «إِنَّ اللهَ كَتَبَ الْحَسَنَاتِ وَالسَّيِّئَاتِ، ثُمَّ بَيَّنَ ذَلِكَ، فَمَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا كَتَبَهَا اللهُ عِنْدَهُ حَسَنَةً كَامِلَةً، وَإِنْ هَمَّ بِهَا فَعَمِلَهَا كَتَبَهَا اللهُ عِنْدَهُ عَشْرَ حَسَنَاتٍ إِلَى سَبْعِمِائَةِ ضِعْفٍ إِلَى أَضْعَافٍ كَثِيرَةٍ، وَإِنْ هَمَّ بِسَيِّئَةٍ فَلَمْ يَعْمَلْهَا كَتَبَهَا اللهُ عِنْدَهُ حَسَنَةً كَامِلَةً، وَإِنْ هَمَّ بِهَا فَعَمِلَهَا كَتَبَهَا اللهُ سَيِّئَةً وَاحِدَةً».'],
e:['From Ibn ʿAbbās, from the Messenger of Allah ﷺ, among what he narrates from his Lord, Blessed and Exalted: “Allah has written down good deeds and bad deeds, then made that clear. Whoever intends a good deed but does not do it, Allah writes it with Him as one complete good deed; and if he intends it and does it, Allah writes it with Him as ten good deeds, up to seven hundred times, up to many times more. Whoever intends a bad deed but does not do it, Allah writes it with Him as one complete good deed; and if he intends it and does it, Allah writes it as one bad deed.”'],
s:'رَوَاهُ الْبُخَارِيُّ وَمُسْلِمٌ',v:[['الْحَسَنَاتُ','good deeds'],['السَّيِّئَاتُ','bad deeds'],['هَمَّ','he intended'],['كَامِلَةً','complete'],['ضِعْفٌ','multiple, times'],['أَضْعَافٌ','many times']]},

{n:38,t:['أَوْلِيَاءُ اللهِ','The friends of Allah'],
a:['عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ ﷺ: «إِنَّ اللهَ تَعَالَى قَالَ: مَنْ عَادَى لِي وَلِيًّا فَقَدْ آذَنْتُهُ بِالْحَرْبِ، وَمَا تَقَرَّبَ إِلَيَّ عَبْدِي بِشَيْءٍ أَحَبَّ إِلَيَّ مِمَّا افْتَرَضْتُهُ عَلَيْهِ، وَلَا يَزَالُ عَبْدِي يَتَقَرَّبُ إِلَيَّ بِالنَّوَافِلِ حَتَّى أُحِبَّهُ.',
'فَإِذَا أَحْبَبْتُهُ كُنْتُ سَمْعَهُ الَّذِي يَسْمَعُ بِهِ، وَبَصَرَهُ الَّذِي يُبْصِرُ بِهِ، وَيَدَهُ الَّتِي يَبْطِشُ بِهَا، وَرِجْلَهُ الَّتِي يَمْشِي بِهَا، وَلَئِنْ سَأَلَنِي لَأُعْطِيَنَّهُ، وَلَئِنِ اسْتَعَاذَنِي لَأُعِيذَنَّهُ».'],
e:['From Abū Hurayrah, who said: The Messenger of Allah ﷺ said: “Allah the Exalted said: Whoever shows enmity to a friend of Mine, I have declared war on him. My servant does not draw near to Me with anything more beloved to Me than what I have made obligatory on him, and My servant keeps drawing near to Me with voluntary deeds until I love him.',
'When I love him, I am his hearing with which he hears, his sight with which he sees, his hand with which he strikes and his foot with which he walks. If he asks Me, I will surely give him; and if he seeks refuge in Me, I will surely grant him refuge.”'],
s:'رَوَاهُ الْبُخَارِيُّ',v:[['عَادَى','he showed enmity'],['وَلِيًّا','a friend (of Allah)'],['آذَنْتُهُ','I declared to him'],['تَقَرَّبَ','he drew near'],['افْتَرَضْتُهُ','I made it obligatory'],['النَّوَافِلُ','voluntary deeds'],['يَبْطِشُ','he strikes, grasps'],['اسْتَعَاذَنِي','he sought refuge in Me'],['لَأُعِيذَنَّهُ','I will surely protect him']]},

{n:39,t:['رَفْعُ الْحَرَجِ','The lifting of blame'],
a:['عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا أَنَّ رَسُولَ اللهِ ﷺ قَالَ: «إِنَّ اللهَ تَجَاوَزَ لِي عَنْ أُمَّتِي الْخَطَأَ وَالنِّسْيَانَ وَمَا اسْتُكْرِهُوا عَلَيْهِ».'],
e:['From Ibn ʿAbbās that the Messenger of Allah ﷺ said: “Allah has pardoned for my sake my nation’s mistakes, forgetfulness, and what they are forced to do.”'],
s:'حَدِيثٌ حَسَنٌ، رَوَاهُ ابْنُ مَاجَهْ وَالْبَيْهَقِيُّ وَغَيْرُهُمَا',v:[['تَجَاوَزَ','He overlooked, pardoned'],['الْخَطَأُ','mistakes'],['النِّسْيَانُ','forgetfulness'],['اسْتُكْرِهُوا','they were forced']]},

{n:40,t:['كُنْ فِي الدُّنْيَا كَأَنَّكَ غَرِيبٌ','Be in this world like a stranger'],
a:['عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَخَذَ رَسُولُ اللهِ ﷺ بِمَنْكِبَيَّ فَقَالَ: «كُنْ فِي الدُّنْيَا كَأَنَّكَ غَرِيبٌ أَوْ عَابِرُ سَبِيلٍ».',
'وَكَانَ ابْنُ عُمَرَ رَضِيَ اللهُ عَنْهُمَا يَقُولُ: إِذَا أَمْسَيْتَ فَلَا تَنْتَظِرِ الصَّبَاحَ، وَإِذَا أَصْبَحْتَ فَلَا تَنْتَظِرِ الْمَسَاءَ، وَخُذْ مِنْ صِحَّتِكَ لِمَرَضِكَ، وَمِنْ حَيَاتِكَ لِمَوْتِكَ.'],
e:['From Ibn ʿUmar, who said: The Messenger of Allah ﷺ took hold of my shoulders and said: “Be in this world as though you were a stranger or a traveller passing through.”',
'Ibn ʿUmar used to say: When evening comes, do not wait for the morning; when morning comes, do not wait for the evening. Take from your health for your illness, and from your life for your death.'],
s:'رَوَاهُ الْبُخَارِيُّ',v:[['مَنْكِبَيَّ','my two shoulders'],['غَرِيبٌ','a stranger'],['عَابِرُ سَبِيلٍ','a traveller passing through'],['أَمْسَيْتَ','evening came on you'],['أَصْبَحْتَ','morning came on you']]},

{n:41,t:['اتِّبَاعُ مَا جَاءَ بِهِ النَّبِيُّ ﷺ','Following what the Prophet ﷺ brought'],
a:['عَنْ أَبِي مُحَمَّدٍ عَبْدِ اللهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ ﷺ: «لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يَكُونَ هَوَاهُ تَبَعًا لِمَا جِئْتُ بِهِ».'],
e:['From Abū Muḥammad ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ, who said: The Messenger of Allah ﷺ said: “None of you truly believes until his desires follow what I have brought.”'],
s:'حَدِيثٌ حَسَنٌ صَحِيحٌ، رُوِّينَاهُ فِي كِتَابِ «الْحُجَّةِ» بِإِسْنَادٍ صَحِيحٍ',v:[['هَوَاهُ','his desires'],['تَبَعًا','following'],['جِئْتُ بِهِ','I have brought']]},

{n:42,t:['سَعَةُ مَغْفِرَةِ اللهِ','The vastness of Allah’s forgiveness'],
a:['عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ ﷺ يَقُولُ: «قَالَ اللهُ تَعَالَى: يَا ابْنَ آدَمَ، إِنَّكَ مَا دَعَوْتَنِي وَرَجَوْتَنِي غَفَرْتُ لَكَ عَلَى مَا كَانَ مِنْكَ وَلَا أُبَالِي.',
'يَا ابْنَ آدَمَ، لَوْ بَلَغَتْ ذُنُوبُكَ عَنَانَ السَّمَاءِ ثُمَّ اسْتَغْفَرْتَنِي غَفَرْتُ لَكَ.',
'يَا ابْنَ آدَمَ، إِنَّكَ لَوْ أَتَيْتَنِي بِقُرَابِ الْأَرْضِ خَطَايَا ثُمَّ لَقِيتَنِي لَا تُشْرِكُ بِي شَيْئًا لَأَتَيْتُكَ بِقُرَابِهَا مَغْفِرَةً».'],
e:['From Anas, who said: I heard the Messenger of Allah ﷺ say: “Allah the Exalted said: O son of Adam, as long as you call on Me and hope in Me, I will forgive you whatever you have done, and I do not mind.',
'O son of Adam, if your sins reached the clouds of the sky and then you asked My forgiveness, I would forgive you.',
'O son of Adam, if you came to Me with nearly the earth’s fill of sins, then met Me without associating anything with Me, I would come to you with nearly its fill of forgiveness.”'],
s:'رَوَاهُ التِّرْمِذِيُّ وَقَالَ: حَدِيثٌ حَسَنٌ صَحِيحٌ',v:[['دَعَوْتَنِي','you called on Me'],['رَجَوْتَنِي','you hoped in Me'],['لَا أُبَالِي','I do not mind'],['عَنَانُ السَّمَاءِ','the clouds of the sky'],['قُرَابٌ','nearly the fill of'],['خَطَايَا','sins'],['مَغْفِرَةً','forgiveness']]}
];

